import re

# Load all business documents with the necessary fields
biz = list(db['business'].find({}, {'business_id':1, 'attributes':1, 'description':1}))
print('total businesses:', len(biz))

US_STATES = {
 'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA',
 'ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK',
 'OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY','DC'
}

def norm_wifi(v):
    if v is None:
        return None
    s = str(v).strip()
    # strip leading u and quotes
    if s.startswith('u') and len(s) > 1 and s[1] in ("'", '"'):
        s = s[1:]
    s = s.strip("'\"").strip().lower()
    return s

def wifi_offered(attrs):
    if not attrs or not isinstance(attrs, dict):
        return False
    val = None
    for k in ('WiFi', 'wifi', 'Wifi', 'WIFI'):
        if k in attrs:
            val = attrs[k]
            break
    nv = norm_wifi(val)
    if nv is None or nv in ('no','none',''):
        return False
    return True

zip_re = re.compile(r'\b([A-Z]{2})\b\s*\d{5}')
comma_re = re.compile(r',\s*([A-Z]{2})\b')

def parse_state(desc):
    if not desc:
        return None
    m = zip_re.search(desc)
    if m:
        st = m.group(1)
        if st in US_STATES:
            return st
    m = comma_re.search(desc)
    if m:
        st = m.group(1)
        if st in US_STATES:
            return st
    return None

records = []
for b in biz:
    if wifi_offered(b.get('attributes')):
        st = parse_state(b.get('description'))
        if st:
            records.append((b['business_id'], st))

print('wifi-offering businesses with valid state:', len(records))

import collections
state_counts = collections.Counter(r[1] for r in records)
print('top 10 states:', state_counts.most_common(10))
